def icon(name, ar=False):
    mirror = ' style="transform:scaleX(-1)"' if ar and name in ('arrow','chevron','follow','exit') else ''
    return f'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"{mirror}><path d="{ICONS[name]}"/></svg>'

def mark(key):
    return f'<svg class="mark" viewBox="0 0 32 32" aria-hidden="true" fill="currentColor">{LOGOS[key][2]}</svg>'

def bd(s): return f'<bdi dir="ltr">{escape(s)}</bdi>'
def choose(ar, en, arabic): return arabic if ar else en
def badge(text, kind=''): return f'<span class="badge {kind}"><i class="dot"></i>{text}</span>'
def button(text, ar=False, secondary=False, arrow=False):
    return f'<button type="button" class="btn {"secondary" if secondary else ""}">{text}{icon("arrow",ar) if arrow else ""}</button>'
def link(text, ar=False): return f'<span class="link">{text}{icon("arrow",ar)}</span>'
def avatar(initials='MH', large=False): return f'<span class="avatar {"large" if large else ""}">{initials}</span>'
def doctor(ar): return choose(ar, 'Dr Mariam Hassan', 'د. مريم حسن')
def patient(ar): return choose(ar, 'Omar Abdelrahman', 'عمر عبدالرحمن')
def clinic(ar): return choose(ar, 'Dokki Clinic', 'عيادة الدقي')
def date(ar): return choose(ar, '2 November 2026', '2 نوفمبر 2026')
def timezone(ar): return choose(ar, 'Cairo time', 'بتوقيت القاهرة')+' '+bd('(UTC+02:00)')

def nav(ar, role, active):
    items = [('care',choose(ar,'My care','متابعتي'),'patient'),('search',choose(ar,'Find care','دور على دكتور'),'find')] if role=='patient' else [('care',choose(ar,'Schedule','جدول المواعيد'),'schedule'),('people',choose(ar,'People in your care','مرضاي'),'people')]
    return ''.join(f'<div class="nav-item {"active" if key==active else ""}">{icon(ic,ar)}<span>{name}</span></div>' for ic,name,key in items)

def shell(key,ar,title,subtitle,body,role='patient',active='patient',page=''):
    spec=DIRECTIONS[key]
    brand=f'<div class="brand">{mark(key+"1")}<span>EgyHealth<em>360</em></span></div>'
    who=choose(ar,'Patient workspace','متابعتك الصحية') if role=='patient' else choose(ar,'Doctor workspace','مساحة الدكتور')
    rail_secondary=f'<div class="label">{choose(ar,"Workspace","مساحتك")}</div><div class="nav-item">{icon("history",ar)}{choose(ar,"Available history","السجل المتاح")}</div>' if role=='patient' else ''
    n=nav(ar,role,active)
    title_block=f'<div class="page-title"><div><div class="eyebrow">{who}<span>·</span>{date(ar)}</div><h1>{title}</h1><p>{subtitle}</p></div><span class="label">{timezone(ar)}</span></div>' if title else ''
    return f'''<!doctype html><html lang="{'ar' if ar else 'en'}" dir="{'rtl' if ar else 'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{spec['name']} — {escape(title or page)} — visual study</title><link rel="stylesheet" href="../screens.css"></head><body class="{key}" dir="{'rtl' if ar else 'ltr'}"><div class="shell {page}">
    <aside class="rail">{brand}<nav class="nav" aria-label="{choose(ar,'Primary','التنقل الرئيسي')}">{n}</nav>{rail_secondary}<div class="rail-bottom"><div class="nav-item">{icon('settings')}{choose(ar,'Account & language','الحساب واللغة')}</div><div class="inline" style="padding:15px 12px">{avatar('OA' if role=='patient' else 'MH')}<div><strong class="small">{patient(ar) if role=='patient' else doctor(ar)}</strong><p class="muted small">{choose(ar,'Personal account','حساب شخصي') if role=='patient' else clinic(ar)}</p></div></div></div></aside>
    <div class="workspace"><header class="topbar">{brand}<nav class="nav">{n}</nav><div class="utility"><span>{who}</span><span>{choose(ar,'English','العربية')}</span>{avatar('OA' if role=='patient' else 'MH')}</div></header><header class="mobile-header">{brand}{avatar('OA' if role=='patient' else 'MH')}</header><main class="content">{title_block}{body}</main><footer class="review-tag">{key.upper()} · {spec['name']} &nbsp; / &nbsp; {choose(ar,'Exploratory visual · synthetic data · controls are appearance specimens','استكشاف بصري · بيانات تجريبية · الأزرار للعرض البصري')}</footer><nav class="mobile-bottom" aria-label="{choose(ar,'Primary','التنقل الرئيسي')}">{n}</nav></div></div></body></html>'''

def appointment(ar, key, mobile=False):
    return f'''<section class="pane appointment"><div class="appt-heading"><div class="between"><span class="label">{choose(ar,'Next appointment','ميعادك الجاي')}</span>{badge(choose(ar,'Booked','محجوز'),'good')}</div></div><div class="appt-inner"><div class="appt-date"><div class="date-tile"><strong>{bd('02')}</strong><span>{choose(ar,'NOV · MON','نوفمبر · الاثنين')}</span></div><div><div class="appt-time">{bd('14:30')}</div><p class="small muted">{timezone(ar)}</p></div></div><div class="doctor inline">{avatar('MH',True)}<div><h2>{doctor(ar)}</h2><p class="muted small">{choose(ar,'Internal medicine','باطنة')} · {clinic(ar)}</p></div></div>{button(choose(ar,'View appointment','تفاصيل الميعاد'),ar,arrow=True)}</div><p class="hint">{choose(ar,'Booking does not give the doctor access to your medical information.','الحجز مش بيدي الدكتور صلاحية يشوف معلوماتك الطبية.')}</p><div class="appointment-foot"><span>{icon('pin')} {clinic(ar)}</span><span>{choose(ar,'In person','في العيادة')}</span></div></section>'''

def retrieval(ar):
    items=[choose(ar,'Appointments','المواعيد'),choose(ar,'Prescriptions','الروشتات'),choose(ar,'Shared summaries & follow-up','ملخصات الزيارات والمتابعة'),choose(ar,'Available history','السجل المتاح'),choose(ar,'Your doctors','دكاترتي')]
    return '<section class="retrieval"><h3>'+choose(ar,'Your information','معلوماتك')+'</h3>'+''.join(f'<div class="retrieval-row"><span>{x}</span>{icon("chevron",ar)}</div>' for x in items)+'</section>'

def care_items(ar):
    items=[('file',choose(ar,'Visit summary','ملخص الزيارة'),choose(ar,'Shared with you','متشارك معاك'),choose(ar,'Dr Mariam Hassan shared your visit summary. Read the recorded instructions in the source.','د. مريم حسن شاركت ملخص الزيارة معاك. اقرأ التعليمات زي ما اتسجّلت في المصدر.'),choose(ar,'Read summary','اقرأ الملخص'),choose(ar,'1 Nov 2026','1 نوفمبر 2026')),
           ('rx',choose(ar,'Your prescription','روشتتك'),choose(ar,'Signed','متوقّعة'),bd('Amoxicillin')+' · '+bd('1.25 mL')+'<br>'+choose(ar,'Synthetic display quantity, not a dose. Pharmacy accepted responsibility; no dispense recorded. Availability is not confirmed.','كمية تجريبية للعرض، مش جرعة. الصيدلية قبلت المسؤولية؛ مفيش صرف متسجّل. التوفّر مش متأكد.'),choose(ar,'View prescription & validity','شوف الروشتة وفترة صلاحيتها'),choose(ar,'1 Nov 2026','1 نوفمبر 2026'))]
    return '<section class="care-list"><div class="section-kicker"><span>'+choose(ar,'Recently shared','اتشارك معاك مؤخرًا')+'</span><span class="muted small">'+choose(ar,'From your doctors','من دكاترتك')+'</span></div>'+''.join(f'<article class="care-item">{icon(ic,ar)}<div><h3>{title}</h3>{badge(status,"neutral")}<p>{text}</p>{link(action,ar)}</div><div class="item-side">{date_text}</div></article>' for ic,title,status,text,action,date_text in items)+'</section>'

def my_care(key,ar):
    follow=f'<section class="pane followup"><span class="label">{choose(ar,"Your next step","خطوتك الجاية")}</span><h2>{choose(ar,"Follow-up recommended","الدكتور موصي بمتابعة")}</h2><p>{choose(ar,"No appointment is linked here. A recommendation does not book a visit.","مفيش ميعاد مربوط بالتوصية هنا. التوصية مش حجز.")}</p>{button(choose(ar,"Find an appointment","دور على ميعاد"),ar,secondary=True,arrow=True)}</section>'
    body=f'<div class="patient-grid"><div class="care-main">{appointment(ar,key)}{care_items(ar)}</div><aside class="care-side">{follow}{retrieval(ar)}</aside></div>'
    return shell(key,ar,choose(ar,'My care','متابعتي'),choose(ar,'Good morning, Omar. Here’s what’s next.','صباح الخير يا عمر. دي خطوتك الجاية.'),body)

def filters(ar):
    groups=[(choose(ar,'Specialty','التخصص'),[choose(ar,'Internal medicine','باطنة'),choose(ar,'All specialties','كل التخصصات')]),(choose(ar,'Location','المكان'),[choose(ar,'Dokki','الدقي'),choose(ar,'All locations','كل الأماكن')]),(choose(ar,'Appointment','الميعاد'),[choose(ar,'Today','النهارده'),choose(ar,'This week','الأسبوع ده')])]
    return '<aside class="filters">'+''.join('<div class="filter-section"><span class="label">'+name+'</span>'+''.join(f'<div class="filter-option"><span class="check {"on" if j==0 else ""}">{"✓" if j==0 else ""}</span>{x}</div>' for j,x in enumerate(vals))+'</div>' for name,vals in groups)+'</aside>'

def booking(ar):
    return f'''<aside class="pane booking-summary"><span class="label">{choose(ar,'Selected appointment','الميعاد اللي اخترته')}</span><h2>{doctor(ar)}</h2><p class="muted small">{choose(ar,'Internal medicine','باطنة')} · {clinic(ar)}</p><div class="detail-row"><span>{choose(ar,'Date','التاريخ')}</span><strong>{date(ar)}</strong></div><div class="detail-row"><span>{choose(ar,'Time','الوقت')}</span><strong>{bd('14:30')}</strong></div><p class="muted small" style="margin-top:10px">{timezone(ar)}</p><div class="detail-row"><span>{choose(ar,'Visit','الزيارة')}</span><strong>{choose(ar,'In person','في العيادة')}</strong></div>{button(choose(ar,'Review booking','راجع الحجز'),ar,arrow=True)}<p class="muted small" style="margin-top:16px">{choose(ar,'Not booked yet. Review the details before confirming. Booking does not grant medical access.','لسه مفيش حجز. راجع التفاصيل قبل التأكيد. الحجز مش بيدي صلاحية للمعلومات الطبية.')}</p></aside>'''

def find_care(key,ar):
    search=f'<div class="searchbar"><div class="search-field">{icon("search")}<div style="width:100%"><label for="specialty">{choose(ar,"Doctor or specialty","اسم الدكتور أو التخصص")}</label><input id="specialty" value="{choose(ar,"Internal medicine","باطنة")}" readonly></div></div><div class="search-field">{icon("pin")}<div style="width:100%"><label for="location">{choose(ar,"Location","المكان")}</label><input id="location" value="{choose(ar,"Dokki, Giza","الدقي، الجيزة")}" readonly></div></div>{button(choose(ar,"Search","دور"),ar)}</div>'
    docs=[(doctor(ar),'MH',clinic(ar),['14:30','15:00','16:00']), (choose(ar,'Dr Youssef Adel','د. يوسف عادل'),'YA',choose(ar,'Tahrir Clinic','عيادة التحرير'),['15:30','16:30','17:00']), (choose(ar,'Dr Salma Nabil','د. سلمى نبيل'),'SN',choose(ar,'Dokki Medical Center','مركز الدقي الطبي'),['16:00','17:00'])]
    results='<section><div class="section-head"><h2>'+choose(ar,'Available appointments','مواعيد متاحة')+'</h2><span class="muted small">'+choose(ar,'Today · Cairo time','النهارده · بتوقيت القاهرة')+'</span></div>'
    for j,(name,initials,place,slots) in enumerate(docs):
        results+=f'<article class="doctor-result"><div class="result-header">{avatar(initials,True)}<div><h3>{name}</h3><p>{choose(ar,"Internal medicine","باطنة")} · {place}</p><p>{icon("pin")} {choose(ar,"Dokki, Giza · In person","الدقي، الجيزة · في العيادة")}</p></div></div><div class="slot-list">'+''.join(f'<button class="slot {"selected" if j==0 and i==0 else ""}">{bd(s)}</button>' for i,s in enumerate(slots))+'</div></article>'
    results+='</section>'
    return shell(key,ar,choose(ar,'Find care','دور على دكتور'),choose(ar,'Choose a doctor, then find a time that works for you.','اختار دكتور وشوف الميعاد المناسب ليك.'),search+f'<div class="find-grid">{filters(ar)}{results}{booking(ar)}</div>',active='find')

def mobile_appointment(key,ar):
    body=f'<div class="mobile-appt"><div class="eyebrow">{choose(ar,"Find care","دور على دكتور")}</div><h1 class="appointment-review-title">{choose(ar,"Your appointment","ميعادك")}</h1>{appointment(ar,key,True)}<h2>{choose(ar,"Appointment details","تفاصيل الميعاد")}</h2><div class="detail-row"><span>{choose(ar,"Date","التاريخ")}</span><strong>{date(ar)}</strong></div><div class="detail-row"><span>{choose(ar,"Location","المكان")}</span><strong>{clinic(ar)}</strong></div><div class="detail-row"><span>{choose(ar,"Doctor","الدكتور")}</span><strong>{doctor(ar)}</strong></div><div class="notice">{choose(ar,"This booking does not give the doctor access to your medical information.","الحجز ده مش بيدي الدكتور صلاحية يشوف معلوماتك الطبية.")}</div><div class="retrieval-row"><span>{choose(ar,"Appointment history","سجل المواعيد")}</span>{icon("chevron",ar)}</div></div>'
    return shell(key,ar,'','',body,active='find',page='appointment-page')

def days(ar):
    names=choose(ar,['Mon','Tue','Wed','Thu','Fri','Sat'],['اثنين','ثلاثاء','أربعاء','خميس','جمعة','سبت'])
    return '<div class="date-strip">'+''.join(f'<div class="day {"selected" if i==0 else ""}"><span>{n}</span><strong>{bd(str(i+2).zfill(2))}</strong></div>' for i,n in enumerate(names))+'</div>'

def schedule(key,ar):
    rows=[('13:30',choose(ar,'Nour Ahmed','نور أحمد'),'NA',choose(ar,'Consulted','الزيارة تمت'),'neutral'),('14:00',choose(ar,'Hana Mahmoud','هنا محمود'),'HM',choose(ar,'Cancelled','ملغي'),'neutral'),('14:30',patient(ar),'OA',choose(ar,'Consultation open','الاستشارة مفتوحة'),''),('15:00',choose(ar,'Ali Mostafa','علي مصطفى'),'AM',choose(ar,'Booked','محجوز'),'good'),('15:30',choose(ar,'Mona Emad','منى عماد'),'ME',choose(ar,'Booked','محجوز'),'good'),('16:00',choose(ar,'Sara Ibrahim','سارة إبراهيم'),'SI',choose(ar,'Booked','محجوز'),'good')]
    table='<table class="schedule-table"><thead><tr>'+''.join('<th>'+x+'</th>' for x in [choose(ar,'Time','الوقت'),choose(ar,'Patient','المريض'),choose(ar,'Visit','الزيارة'),choose(ar,'Status','الحالة'),choose(ar,'Action','الإجراء')])+'</tr></thead><tbody>'
    for i,(time,name,initials,status,kind) in enumerate(rows):
        table+=f'<tr class="{"current" if i==2 else ""}"><td>{bd(time)}</td><td><div class="inline">{avatar(initials)}<div><strong>{name}</strong><p class="muted">{choose(ar,"Synthetic patient","مريض تجريبي")}</p></div></div></td><td>{choose(ar,"In person","في العيادة")}</td><td>{badge(status,kind)}</td><td>{link(choose(ar,"Resume","كمّل"),ar) if i==2 else link(choose(ar,"Details","التفاصيل"),ar)}</td></tr>'
    table+='</tbody></table>'
    aside=f'<aside class="pane schedule-aside"><span class="label">{choose(ar,"Selected visit","الزيارة المختارة")}</span>{avatar("OA",True)}<h2>{patient(ar)}</h2><p class="muted small">{bd("EH-DEMO-204")} · {clinic(ar)}</p><div class="detail-row"><span>{choose(ar,"Appointment","الميعاد")}</span><strong>{bd("14:30")}</strong></div><div class="detail-row"><span>{choose(ar,"Consultation","الاستشارة")}</span><strong>{choose(ar,"Open","مفتوحة")}</strong></div><div class="notice">{choose(ar,"Current care assignment permits this consultation. Booking alone does not grant clinical access.","علاقة الرعاية الحالية بتسمح بالاستشارة دي. الحجز لوحده مش بيدي صلاحية طبية.")}</div>{button(choose(ar,"Resume consultation","كمّل الاستشارة"),ar,arrow=True)}<div class="workload"><strong>{bd("03")}</strong><small>{choose(ar,"Booked visits remaining today","زيارات محجوزة باقية النهارده")}</small></div></aside>'
    body=f'<div class="schedule-layout"><section class="schedule-main"><div class="schedule-tools"><strong>{choose(ar,"November 2026","نوفمبر 2026")}</strong><span class="muted small">{clinic(ar)} · {timezone(ar)}</span></div>{days(ar)}{table}<p class="muted small" style="margin-top:20px">{choose(ar,"Appointment states describe visits. They do not grant clinical authority.","حالة الميعاد بتوصف الزيارة؛ مش بتدي صلاحية طبية.")}</p></section>{aside}</div>'
    return shell(key,ar,choose(ar,'Schedule','جدول المواعيد'),choose(ar,'Your day, with the right context for each visit.','يومك وتفاصيل كل زيارة في مكانها.'),body,'doctor','schedule')

def consultation(key,ar):
    context=f'''<aside class="pane context-panel"><h3>{choose(ar,'Clinical context','السياق الطبي')}</h3><div class="datum"><span>{choose(ar,'Visit reason','سبب الزيارة')}</span><strong>{choose(ar,'Recorded follow-up visit','زيارة متابعة متسجّلة')}</strong></div><div class="datum"><span>{choose(ar,'Available sources','المصادر المتاحة')}</span><strong>{choose(ar,'Permitted sources only','المصادر المسموح بيها بس')}</strong></div><div class="vitals"><div><strong>{bd('128/82')}</strong><small>{bd('mmHg')}</small></div><div><strong>{bd('72')}</strong><small>{bd('bpm')}</small></div></div><div class="notice"><strong>{choose(ar,'Allergies not reviewed','الحساسية لسه متراجعتش')}</strong><p>{choose(ar,'Not reviewed does not mean no known allergies.','عدم المراجعة مش معناه مفيش حساسية معروفة.')}</p></div></aside>'''
    tabs='<div class="local-tabs">'+''.join(f'<span class="{"selected" if i==0 else ""}">{x}</span>' for i,x in enumerate([choose(ar,'Documentation','التوثيق'),choose(ar,'Prescription','الوصفة الطبية'),choose(ar,'Follow-up','المتابعة')]))+'</div>'
    note=f'''<section class="pane note-pane">{tabs}<div class="between"><h2>{icon('lock')} {choose(ar,'Private note','ملاحظات خاصة')}</h2>{badge(choose(ar,'Draft saved · 14:42','المسودة محفوظة · 14:42'),'neutral')}</div><p class="muted small" style="margin-top:10px">{choose(ar,'Only the permitted author can read this note. Signing keeps it private.','الملاحظات دي للمؤلف المسموح له بس. التوقيع مش بيشاركها مع المريض.')}</p><label class="label" for="note" style="display:block;margin-top:18px">{choose(ar,'Recorded findings','الملاحظات المتسجّلة')}</label><textarea class="note-field" id="note" readonly>{choose(ar,'Synthetic recorded note: patient attended to review previously shared instructions. Medication history has not been reconciled in this example. Allergy review remains pending. No automated assessment.','ملاحظة تجريبية: المريض حضر لمراجعة التعليمات اللي اتشاركت قبل كده. تاريخ الأدوية لسه متراجعش في المثال ده. مراجعة الحساسية لسه معلّقة. مفيش تقييم آلي.')}</textarea><div class="action-row">{button(choose(ar,'Save draft','احفظ المسودة'),ar,secondary=True)}{button(choose(ar,'Review private-note signing','راجع توقيع الملاحظات الخاصة'),ar)}</div><section class="released"><div class="between"><h3>{choose(ar,'Visit summary','ملخص الزيارة')}</h3>{badge(choose(ar,'Signed & shared','متوقّع ومتشارك'),'good')}</div><p>{choose(ar,'Visible to the patient. Private notes remain private.','المريض يقدر يقرأ الملخص ده. الملاحظات الخاصة هتفضل خاصة.')}</p><p>{doctor(ar)} · {date(ar)} · {bd('14:40 UTC+02:00')}</p></section><section class="released"><div class="between"><h3>{choose(ar,'Follow-up recommendation','توصية المتابعة')}</h3>{badge(choose(ar,'Shared','متشاركة'),'neutral')}</div><p>{choose(ar,'No appointment is linked. This recommendation does not book a visit.','مفيش ميعاد مربوط بالتوصية. التوصية دي مش بتحجز زيارة.')}</p></section></section>'''
    rx=f'''<aside class="pane rx-panel"><div class="between"><h2>{choose(ar,'Prescription','وصفة طبية')}</h2>{badge(choose(ar,'Signed','متوقّعة'),'neutral')}</div><h3>{bd('Amoxicillin')}</h3><p>{choose(ar,'Synthetic display quantity, not a dose.','كمية تجريبية للعرض، مش جرعة.')} {bd('1.25 mL')}</p><div class="detail-row"><span>{choose(ar,'Valid from','صالحة من')}</span><strong>{date(ar)} · {bd('14:20')}</strong></div><div class="detail-row"><span>{choose(ar,'Valid until','صالحة لحد')}</span><strong>{choose(ar,'5 November 2026','5 نوفمبر 2026')} · {bd('14:20')}</strong></div><p>{timezone(ar)}</p><div class="rule"></div><span class="label">{choose(ar,'Pharmacy responsibility','مسؤولية الصيدلية')}</span><p style="color:var(--ink)"><strong>{choose(ar,'Accepted by pharmacy','الصيدلية قبلت المسؤولية')}</strong></p><p>{choose(ar,'No dispense recorded. Acceptance does not confirm stock or pickup readiness.','مفيش صرف متسجّل. قبول المسؤولية مش تأكيد لتوفّر الدوا أو تجهيزه للاستلام.')}</p><div class="rule"></div><p>{choose(ar,'Instructions remain exactly as recorded in the signed source.','التعليمات بتفضل زي ما اتسجّلت في المصدر المتوقّع.')}</p>{link(choose(ar,'Open signed source','افتح المصدر المتوقّع'),ar)}</aside>'''
    head=f'<div class="patient-bar"><div class="inline">{avatar("OA",True)}<div><span class="label">{choose(ar,"Active consultation","الاستشارة الحالية")}</span><h1>{patient(ar)}</h1><p>{bd("EH-DEMO-204")} · {clinic(ar)} · {date(ar)} · {bd("14:30 UTC+02:00")}</p></div></div><div class="badges">{badge(choose(ar,"Consultation open","الاستشارة مفتوحة"))}{badge(choose(ar,"Current care access","صلاحية رعاية حالية"),"good")}</div></div>'
    close=f'<div class="closebar"><div><strong>{choose(ar,"Review & close","المراجعة والإغلاق")} · {patient(ar)}</strong><p>{choose(ar,"Closing does not save, sign or share other content. Review the exact source states before closing.","الإغلاق مش بيحفظ أو يوقّع أو يشارك المحتوى التاني. راجع حالة كل مصدر قبل الإغلاق.")}</p></div>{button(choose(ar,"Review closure","راجع الإغلاق"),ar,secondary=True,arrow=True)}</div>'
    return shell(key,ar,'','',head+f'<div class="consult-grid">{context}{note}{rx}</div>'+close,'doctor','schedule','consultation')

def doctor_mobile(key,ar):
    body=f'<div class="mobile-doctor-page"><div class="eyebrow">{clinic(ar)} · {date(ar)}</div><h1>{choose(ar,"Your afternoon","مواعيد بعد الظهر")}</h1><p class="muted small" style="margin-top:8px">{timezone(ar)}</p>{days(ar)}<div class="timeline-slot"><time>{bd("14:00")}</time><div><strong>{choose(ar,"Hana Mahmoud","هنا محمود")}</strong><p>{choose(ar,"Cancelled","ملغي")}</p></div></div><div class="timeline-slot active"><time>{bd("14:30")}</time><div><strong>{patient(ar)}</strong><p>{choose(ar,"Consultation open · In person","الاستشارة مفتوحة · في العيادة")}</p></div></div><div class="timeline-slot"><time>{bd("15:00")}</time><div><strong>{choose(ar,"Ali Mostafa","علي مصطفى")}</strong><p>{choose(ar,"Booked · In person","محجوز · في العيادة")}</p></div></div><section class="pane visit-review"><span class="label">{choose(ar,"Selected visit","الزيارة المختارة")}</span><h2>{patient(ar)}</h2><p>{bd("EH-DEMO-204")} · {clinic(ar)}</p><div style="margin-top:15px">{badge(choose(ar,"Current care access","صلاحية رعاية حالية"),"good")}</div><div class="detail-row"><span>{choose(ar,"Appointment","الميعاد")}</span><strong>{bd("14:30")} · {date(ar)}</strong></div><div class="notice">{choose(ar,"Current care assignment permits visit review. Booking alone does not grant access.","علاقة الرعاية الحالية بتسمح بمراجعة الزيارة. الحجز لوحده مش بيدي صلاحية.")}</div>{button(choose(ar,"Review visit details","راجع تفاصيل الزيارة"),ar,arrow=True)}<p style="margin-top:15px">{choose(ar,"For documentation, signing or closing, continue in the full consultation workspace.","للتوثيق أو التوقيع أو الإغلاق، كمّل في مساحة الاستشارة الكاملة.")}</p></section></div>'
    return shell(key,ar,'','',body,'doctor','schedule','doctor-mobile')

def states(key,ar):
    entries=[('01 / Loading','01 / تحميل',choose(ar,'Loading appointments','بنحمّل مواعيدك'),choose(ar,'Your chosen language stays in place while content loads.','اللغة اللي اخترتها بتفضل موجودة لحد ما التحميل يخلص.'),'loading'),('02 / Empty','02 / مفيش مواعيد',choose(ar,'No upcoming appointments','مفيش مواعيد جاية'),choose(ar,'When you book an appointment, you’ll find it here.','لما تحجز ميعاد هتلاقيه هنا.'),'empty'),('03 / Read error','03 / مشكلة في التحميل',choose(ar,'Appointments could not load','المواعيد متحمّلتش'),choose(ar,'Your appointments have not changed. Try loading them again.','مواعيدك متغيّرتش. جرّب تحميلها تاني.'),'error'),('04 / Warning','04 / تنبيه',choose(ar,'Allergies not reviewed','الحساسية لسه متراجعتش'),choose(ar,'Not reviewed does not mean no known allergies. Review the available source before acting.','عدم المراجعة مش معناه مفيش حساسية معروفة. راجع المصدر المتاح قبل أي إجراء.'),'warning'),('05 / Uncertain outcome','05 / النتيجة مش متأكدة',choose(ar,'Signing outcome is not confirmed','نتيجة التوقيع مش متأكدة'),choose(ar,'We could not confirm whether signing completed. Check the exact source before starting a new signing action.','مش قادرين نأكد إذا التوقيع تم. راجع المصدر نفسه قبل ما تبدأ توقيع جديد.'),'uncertain'),('06 / Confirmed','06 / اتأكد',choose(ar,'Summary signed and shared','الملخص اتوقّع واتشارك'),choose(ar,'The patient can read this summary. Private notes remain private.','المريض يقدر يقرأ الملخص ده. الملاحظات الخاصة هتفضل خاصة.'),'success'),('07 / Unavailable','07 / غير متاح',choose(ar,'This information is unavailable','المعلومات دي مش متاحة'),choose(ar,'Return to your available information.','ارجع للمعلومات المتاحة ليك.'),'unavailable')]
    body='<div class="state-grid">'
    for en,arabic,title,copy,state in entries:
        extra='<div class="skeleton"></div><div class="skeleton short"></div>' if state=='loading' else button(choose(ar,'Load again','حمّل تاني'),ar,secondary=True) if state=='error' else button(choose(ar,'Check source state','راجع حالة المصدر'),ar,secondary=True) if state=='uncertain' else button(choose(ar,'Find care','دور على دكتور'),ar,secondary=True) if state=='empty' else ''
        body+=f'<section class="pane state-{state}"><div class="state-label"><span>{choose(ar,en,arabic)}</span>{icon("check" if state=="success" else "info")}</div><h2>{title}</h2><p>{copy}</p><div style="margin-top:12px">{extra}</div></section>'
    body+='</div>'
    return shell(key,ar,choose(ar,'State language','لغة الحالات'),choose(ar,'Meaning comes from words, structure and color together.','المعنى بيظهر بالكلام والشكل واللون مع بعض.'),body,page='states')

def typography(key,ar):
    spec=DIRECTIONS[key]
    swatches=lambda colors:'<div class="swatches">'+''.join(f'<div class="swatch"><i style="--swatch:{c}"></i><span>{c}</span></div>' for c in colors)+'</div>'
    body=f'''<div class="type-grid"><section class="pane"><div class="label">{spec['type']} · {choose(ar,'Typography exploration','استكشاف الخطوط')}</div><div class="type-row"><div class="type-display" lang="ar" dir="rtl">متابعتك أوضح.<br>وكل خطوة في مكانها.</div><div class="type-display" lang="en" dir="ltr">Your care,<br>clearly connected.</div></div><div class="type-row"><div class="label">{choose(ar,'Patient reading · 14 / 25 Arabic','قراءة المريض · عربي 14 / 25')}</div><p lang="ar" dir="rtl" style="font-family:var(--arabic)">د. مريم حسن شاركت ملخص الزيارة معاك. اقرأ التعليمات زي ما اتسجّلت في المصدر. الملاحظات الخاصة هتفضل خاصة.</p><p lang="en" dir="ltr">Your visit summary is ready to read. Your doctor’s private notes remain private.</p></div><div class="type-row"><div class="label">{choose(ar,'Clinical density · 12–14 / 20–25','كثافة طبية · 12–14 / 20–25')}</div><div class="density-line"><span>Amoxicillin</span><strong>{bd('1.25 mL')}</strong></div><div class="density-line"><span>{choose(ar,'Recorded BP','ضغط متسجّل')}</span><strong>{bd('128/82 mmHg')}</strong></div><div class="density-line"><span>{choose(ar,'Visit reference','مرجع الزيارة')}</span><strong>{bd('EH-DEMO-204')}</strong></div><p class="small" lang="ar" dir="rtl">مراجعة {bd('Amoxicillin')} · كمية عرض {bd('1.25 mL')} · {bd('14:30')} · {bd('UTC+02:00')}</p></div><div class="type-row"><div class="label">{choose(ar,'Numerals / joining / diacritics','الأرقام / اتصال الحروف / التشكيل')}</div><p style="font-size:22px">{bd('0123456789 · 0O 1Il · 1.25 / 12.5')}</p><p lang="ar" dir="rtl" style="font-family:var(--arabic);font-size:21px;line-height:2.1">مُتابعة طبية · شُرْب · مسؤولية · لا · لأ · لإ · لآ</p><p lang="ar" dir="rtl" class="small">د. عبدالرحمن محمد عبدالعزيز مصطفى · {bd('2 November 2026')} · {bd('14:30 UTC+02:00')}</p></div></section><section class="pane"><h2>{choose(ar,'Palette studies','استكشاف الألوان')}</h2><p class="muted small">{choose(ar,'Two exploratory combinations. Neither is approved.','مجموعتين للاستكشاف. مفيش ألوان معتمدة.')}</p>{swatches(spec['colors'])}<div class="palette-variant"><span class="label">{choose(ar,'Alternate study','استكشاف بديل')}</span>{swatches(spec['alternate'])}</div><div class="rule"></div><h2>{choose(ar,'Surface & control language','لغة الأسطح والتحكم')}</h2><div class="surface-proof"><div class="pane"><span class="label">{choose(ar,'Contained task','مهمة مجمّعة')}</span><h3>{choose(ar,'Visit summary','ملخص الزيارة')}</h3><p class="muted small">{choose(ar,'A boundary has a purpose.','كل حد بصري ليه غرض.')}</p></div><div><div class="density-line"><span>{choose(ar,'Appointment','الميعاد')}</span>{bd('14:30')}</div><div class="density-line"><span>{choose(ar,'Doctor','الدكتور')}</span>{doctor(ar)}</div></div></div><div class="action-row">{button(choose(ar,'Continue','كمّل'),ar)}{button(choose(ar,'Review details','راجع التفاصيل'),ar,True)}</div><div class="action-row"><span class="btn secondary focus-proof">{choose(ar,'Keyboard focus','تركيز لوحة المفاتيح')}</span>{badge(choose(ar,'Shared','متشارك'),'good')}{badge(choose(ar,'Needs review','محتاج مراجعة'),'warn')}</div><div class="icon-proof">{''.join(icon(x,ar) for x in ['care','search','file','rx','lock','follow'])}</div><p class="muted small">{choose(ar,'Directional arrows mirror; medication names, digits and medical quantities do not.','الأسهم الاتجاهية بتنعكس؛ أسماء الأدوية والأرقام والكميات الطبية بتفضل زي ما هي.')}</p><div class="rule"></div><h2>{choose(ar,'Type & spacing rhythm','إيقاع الخط والمسافات')}</h2><p class="small muted">{choose(ar,'4 / 8 / 12 / 16 / 24 / 32 px. Patient body 14px, clinical body 13px; Arabic line height 1.8. Tabular Latin numerals; no Arabic tracking. Dense labels remain secondary.','4 / 8 / 12 / 16 / 24 / 32 بكسل. نص المريض 14، والنص الطبي 13؛ ارتفاع السطر العربي 1.8. أرقام لاتينية ثابتة العرض، من غير توسيع للحروف العربية.')}</p></section></div>'''
    return shell(key,ar,choose(ar,'Typography & visual language','الخطوط واللغة البصرية'),choose(ar,'A bilingual system designed together, with mixed medical content.','العربي والإنجليزي متصممين مع بعض، بمحتوى طبي مختلط.'),body,page='typography')

def review_css():
    return '''@font-face{font-family:Inter;src:url('../../apps/web/public/fonts/inter-latin-variable.woff2')}@font-face{font-family:Noto;src:url('../../apps/web/public/fonts/noto-sans-arabic-variable.woff2')}*{box-sizing:border-box}body{margin:0;background:#eef2f5;color:#18242e;font:14px/1.7 Inter,Noto,sans-serif}h1,h2,h3,p{margin:0}h1{font-size:44px;letter-spacing:-1.8px;font-weight:550;line-height:1.2}h2{font-size:26px;letter-spacing:-.8px;font-weight:550}h3{font-size:18px;font-weight:600}a{color:inherit;text-underline-offset:4px}a:focus-visible{outline:3px solid #006b99;outline-offset:3px}header{padding:36px 5vw;background:#fff;border-bottom:1px solid #d3dce3}main{padding:36px 5vw}p{margin-top:12px;max-width:900px;color:#526372}.eyebrow{font-size:11px;letter-spacing:.1em;text-transform:uppercase;margin-bottom:12px;color:#526372}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.direction{background:#fff;border:1px solid #d3dce3;padding:24px}.direction>img{width:100%;margin:22px 0;border:1px solid #d3dce3}.direction>a{display:block;font-weight:600}.links{display:flex;gap:15px;flex-wrap:wrap;margin-top:20px;font-size:12px}.section{margin-top:36px}.screen-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;margin-top:24px}.screen{background:white;border:1px solid #d3dce3;padding:18px;min-width:0}.screen img{width:100%;display:block;margin-top:12px}.screen.mobile img{max-width:320px;margin:12px auto 0}.screen .links{margin-top:10px}.logo-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.logo-grid img{width:100%;margin-top:16px}.board{background:#eaf0f3}.board header{padding:30px 40px}.board main{padding:28px 40px}.board h1{font-size:38px}.board-layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:24px}.board .desktop-frame{width:100%;display:block;border:1px solid #cbd6df}.board .mobile-frame{width:100%;border:1px solid #cbd6df}.board-bottom{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:24px}.board-bottom img{width:100%;border:1px solid #cbd6df}.board-label{font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#536576;margin:8px 0}.board .logo-mini{background:#fff;display:flex;align-items:center;gap:16px;padding:18px;margin-bottom:20px}.logo-mini img{width:40px;height:40px}.board .swatches{display:flex;gap:6px;margin-top:15px}.board .swatches i{display:block;width:36px;height:20px;background:var(--c);border:1px solid #b5c1cc}.comparison-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.comparison-grid img{width:100%;display:block;margin-top:12px;border:1px solid #cbd6df}.comparison-grid article{min-width:0}.comparison-grid .mobile-compare{width:65%;margin:15px auto}.compare-label{margin-block:25px 10px;border-top:1px solid #cbd6df;padding-top:18px;font-size:12px}.notice{padding:14px 18px;background:#e6edf3;border-left:3px solid #155b83;margin-top:20px;font-size:13px}.table{width:100%;border-collapse:collapse;margin-top:25px}.table td,.table th{text-align:start;vertical-align:top;padding:15px;border:1px solid #cbd6df;font-size:13px}.table th{background:#fff}.board .mood{font-size:13px;max-width:none;margin-top:8px}@media(max-width:850px){.grid,.screen-grid,.logo-grid,.comparison-grid{grid-template-columns:1fr}h1{font-size:32px}.board-layout{grid-template-columns:1fr}.board .mobile-frame{max-width:300px}.board-bottom{grid-template-columns:1fr}header,main{padding:25px}.table{display:block;overflow:auto}}'''

SCREENS=[('patient','Patient · My care',my_care,1440),('find','Patient · Find care / booking',find_care,1440),('patient-mobile','Patient mobile · My care',my_care,390),('appointment-mobile','Patient mobile · Appointment',mobile_appointment,390),('schedule','Doctor · Schedule',schedule,1440),('consultation','Doctor · Active consultation',consultation,1440),('doctor-mobile','Doctor mobile · Visit review',doctor_mobile,390),('states','Loading / empty / error / warning / uncertain',states,1440),('typography','Typography / palette / surfaces',typography,1440)]

def review_page(title,body,prefix=''):
    return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="{prefix}review.css"></head><body><header><div class="eyebrow">EgyHealth 360 / Visual directions V2 / Product Owner review</div><h1>{title}</h1><p>Exploratory proposals. No selected direction, logo, palette or typeface. Accepted UX, IA and content remain the foundation.</p><div class="links"><a href="{prefix}index.html">All three directions</a><a href="{prefix}comparison.html">Equivalent-content comparison</a><a href="{prefix}logos.html">All six logos</a></div></header><main>{body}</main></body></html>'

def logo_files():
    for ident,(name,rationale,shape,risk) in LOGOS.items():
        c=DIRECTIONS[ident[0]]['primary']
        (ROOT/'assets'/f'{ident}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" fill="{c if ident[0]!='f' else '#236477'}"><title>{ident.upper()} — {name}</title>{shape}</svg>')
        # Browser proof, not scaled-up fake small pixels. Each slot has literal CSS width.
        strips=''
        for label,bg,fg in [('Color / light','#fff',c if ident[0]!='f' else '#236477'),('Reverse / dark','#11171d','#fff'),('Monochrome','#fff','#111')]:
            samples=''.join(f'<div style="display:grid;justify-items:center;gap:12px;min-width:65px"><svg width="{s}" height="{s}" viewBox="0 0 32 32" fill="{fg}" role="img" aria-label="{ident} at {s} pixels">{shape}</svg><small style="font-size:10px">{s}px</small></div>' for s in [16,24,32])
            strips+=f'<div style="background:{bg};color:{fg};padding:22px;display:flex;align-items:center;justify-content:space-between;gap:15px;border:1px solid #d3dce3"><span style="font-size:11px;width:100px">{label}</span>{samples}</div>'
        app=f'<div style="display:flex;gap:18px;align-items:center;margin-top:22px"><div style="width:68px;height:68px;border-radius:16px;background:{c if ident[0]!="f" else "#203f4a"};display:grid;place-items:center"><svg width="40" height="40" viewBox="0 0 32 32" fill="{ "#fff" if ident[0]!="f" else c}">{shape}</svg></div><div><strong style="font-size:19px">EgyHealth <small>360</small></strong><div lang="ar" dir="rtl" style="font-family:Noto,sans-serif;font-size:13px;text-align:start">متابعتي · دور على دكتور</div></div></div>'
        html=review_page(ident.upper()+' — '+name,f'<p style="margin-bottom:22px">{rationale}</p>{strips}{app}<p>{risk}</p><div class="notice">Small marks are rendered at actual 16 / 24 / 32 CSS pixels. No medical symbol, no “complete 360” claim. Preliminary visual screening only; no legal clearance.</div>')
        (ROOT/f'{ident}-proof.html').write_text(html)

def generate():
    (ROOT/'review.css').write_text(review_css())
    inventory=[]
    for key,spec in DIRECTIONS.items():
        folder=ROOT/f'direction-{key}';folder.mkdir(exist_ok=True)
        for stem,label,render,width in SCREENS:
            for lang in ['en','ar']:
                path=f'direction-{key}/{stem}-{lang}.html'
                (ROOT/path).write_text(render(key,lang=='ar'))
                inventory.append(dict(direction=key,screen=stem,language=lang,path=path,width=width,height=900 if width>800 else 844))
        overview=f'<div class="notice">{spec["mood"]} {spec["logic"]} Typography study: {spec["type"]}. {spec["risk"]}</div><section class="logo-grid section">'
        for i in [1,2]:
            ident=key+str(i);name,rationale,_,risk=LOGOS[ident]
            overview+=f'<article class="direction"><h2>{ident.upper()} · {name}</h2><p>{rationale}</p><a href="../{ident}-proof.html"><img src="../{ident}-proof.png" alt="{ident.upper()} small-size, mono and app-icon proof"></a><p>{risk}</p></article>'
        overview+='</section><section class="screen-grid">'
        for stem,label,_,width in SCREENS:
            overview+=f'<article class="screen {"mobile" if width<800 else ""}"><h3>{label}</h3><div class="links"><a href="{stem}-en.html">English HTML</a><a href="{stem}-ar.html">Arabic RTL HTML</a><a href="{stem}-en.png">English PNG</a><a href="{stem}-ar.png">Arabic PNG</a></div><a href="{stem}-ar.png"><img src="{stem}-ar.png" alt="Arabic {label}"></a></article>'
        overview+='</section>'
        (folder/'index.html').write_text(review_page(key.upper()+' — '+spec['name'],overview,'../'))
        swatches=''.join(f'<i style="--c:{c}"></i>' for c in spec['colors'])
        board=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><title>{spec['name']} — presentation board</title><link rel="stylesheet" href="../review.css"></head><body class="board"><header><div class="between"><div class="eyebrow">EgyHealth 360 / Direction {key.upper()} / Exploratory / No selection</div><h1>{spec['name']}</h1></div><p class="mood">{spec['mood']} {spec['logic']}</p></header><main><div class="board-layout"><section><div class="board-label">Patient / My care / English / 1440px source</div><img class="desktop-frame" src="patient-en.png" alt="Patient desktop"><div class="board-bottom"><div><div class="board-label">Doctor / Schedule / English</div><img src="schedule-en.png" alt="Doctor schedule"></div><div><div class="board-label">Doctor / Active consultation / Arabic RTL</div><img src="consultation-ar.png" alt="Arabic consultation"></div></div></section><aside><div class="board-label">Two distinct logo concepts</div><div class="logo-mini"><img src="../assets/{key}1.svg" alt="{key}1"><img src="../assets/{key}2.svg" alt="{key}2"><small>{key.upper()}1 / {key.upper()}2</small></div><h3>{spec['type']}</h3><p class="mood" lang="ar" dir="rtl">متابعتك أوضح، وكل خطوة في مكانها.</p><div class="swatches">{swatches}</div><div class="board-label" style="margin-top:25px">Patient / My care / Arabic / 390px source</div><img class="mobile-frame" src="patient-mobile-ar-viewport.png" alt="Arabic mobile patient"></aside></div><p class="mood">Review question: Would you want to use and show this product? Patient / doctor fit, Arabic quality, identity and remaining refinements require Product Owner judgment. No calculated winner.</p></main></body></html>'''
        (folder/'board.html').write_text(board)
    logo_files()
    cards=''
    for key,spec in DIRECTIONS.items():
        cards+=f'<article class="direction"><div class="eyebrow">Direction {key.upper()}</div><h2>{spec["name"]}</h2><p>{spec["mood"]}</p><a href="direction-{key}/board.png"><img src="direction-{key}/board.png" alt="{spec["name"]} presentation board"></a><a href="direction-{key}/index.html">Open all screens, typography and logo studies →</a><div class="links"><a href="direction-{key}/board.html">Board HTML</a><a href="direction-{key}/patient-mobile-ar.html">Arabic mobile</a><a href="direction-{key}/consultation-en.html">Consultation</a></div></article>'
    body=f'<div class="notice">A / B / C are rejected as current final-direction candidates. This package contains exactly three new directions: D / E / F. No final brand or production implementation is authorized. Synthetic data throughout.</div><section class="grid section">{cards}</section><section class="section"><h2>Review the same content side by side</h2><p><a href="comparison.html">Desktop patient + Arabic mobile + clinician comparison</a> · <a href="logos.html">Six new logo concepts, actual 16/24/32px proofs</a> · <a href="README.md">Delivery and evidence</a></p><p>Choose a direction, request named refinements, reject all, or request a coherent hybrid for a further review. No automatic recommendation, score or winner.</p></section>'
    (ROOT/'index.html').write_text(review_page('Three new ways to make care clear.',body))
    comparison=''
    for stem,label in [('patient-en','Desktop Patient · My care · English'),('patient-mobile-ar','Mobile Patient · My care · Arabic RTL'),('consultation-en','Desktop Doctor · Active consultation · English')]:
        comparison+=f'<div class="compare-label">{label} / Identical facts and tasks / Equal source and display widths</div><div class="comparison-grid">'
        for key,spec in DIRECTIONS.items():
            comparison+=f'<article><h3>{key.upper()} — {spec["name"]}</h3><a href="direction-{key}/{stem}.png"><img class="{"mobile-compare" if "mobile" in stem else ""}" src="direction-{key}/{stem}.png" alt="{spec["name"]} {label}"></a></article>'
        comparison+='</div>'
    (ROOT/'comparison.html').write_text(review_page('Equivalent content. Three distinct systems.',comparison))
    logos='<div class="logo-grid">'
    for ident,(name,rationale,_,risk) in LOGOS.items():
        logos+=f'<article class="direction"><h2>{ident.upper()} · {name}</h2><p>{rationale}</p><a href="{ident}-proof.html"><img src="{ident}-proof.png" alt="{ident} original symbol, small and mono proofs"></a><p>{risk}</p></article>'
    (ROOT/'logos.html').write_text(review_page('Six new identity studies.',logos+'</div>'))
    (ROOT/'evidence'/'inventory.json').write_text(json.dumps(inventory,indent=2)+'\n')
    fixture=dict(patient_en='Omar Abdelrahman',patient_ar='عمر عبدالرحمن',reference='EH-DEMO-204',doctor_en='Dr Mariam Hassan',doctor_ar='د. مريم حسن',clinic='Dokki Clinic',appointment='2026-11-02T14:30:00+02:00',timezone='Africa/Cairo',medicine='Amoxicillin',quantity='1.25 mL',quantity_meaning='Synthetic display quantity, not dosage',bp='128/82 mmHg',pulse='72 bpm',clinical_access='Current assignment in consultation examples; booking grants zero authority',summary='Explicitly signed and shared',note='Private saved draft; signing remains private',pharmacy='Accepted responsibility; no dispense recorded; stock/readiness not confirmed',followup='Shared recommendation; no booking linked')
    (ROOT/'evidence'/'synthetic-fixture.json').write_text(json.dumps(fixture,ensure_ascii=False,indent=2)+'\n')
    (ROOT/'evidence'/'direction-data.json').write_text(json.dumps(DIRECTIONS,indent=2)+'\n')
    print(f'Generated {len(inventory)} bilingual screen specimens, 3 boards, 6 new logo proofs, review and comparison.')

if __name__=='__main__': generate()
